inSequence.script:
var partnerCode = mc.getProperty("partnerCode");
                var accessKey = mc.getProperty("accessKey");
                var secretKey = mc.getProperty("secretKey");
                var orderId = mc.getProperty("orderId");
                var amount = mc.getProperty("amount");
                var orderInfo = mc.getProperty("orderInfo");
                var redirectUrl = mc.getProperty("redirectUrl");
                var ipnUrl = mc.getProperty("ipnUrl");
                var requestId = mc.getProperty("requestId");
                var requestType = "captureWallet";
                var extraData = "";

                // Nối chuỗi Raw Data
                var rawSignature = "accessKey=" + accessKey + "&amount=" + amount + "&extraData=" + extraData + "&ipnUrl=" + ipnUrl + "&orderId=" + orderId + "&orderInfo=" + orderInfo + "&partnerCode=" + partnerCode + "&redirectUrl=" + redirectUrl + "&requestId=" + requestId + "&requestType=" + requestType;

                // Băm HMAC-SHA256
                var Mac = Packages.javax.crypto.Mac;
                var SecretKeySpec = Packages.javax.crypto.spec.SecretKeySpec;
                var String = Packages.java.lang.String;
                var secretKeySpec = new SecretKeySpec(new String(secretKey).getBytes("UTF-8"), "HmacSHA256");
                var mac = Mac.getInstance("HmacSHA256");
                mac.init(secretKeySpec);
                var hmacData = mac.doFinal(new String(rawSignature).getBytes("UTF-8"));

                // Convert sang Hex String
                var formatter = new Packages.java.util.Formatter();
                for (var i = 0; i < hmacData.length; i++) {
                    formatter.format("%02x", new Packages.java.lang.Byte(hmacData[i]));
                }
                var signature = formatter.toString();

                // Đóng gói JSON gửi MoMo
                var momoPayload = {
                    "partnerCode": partnerCode,
                    "requestId": requestId,
                    "amount": parseInt(amount),
                    "orderId": orderId,
                    "orderInfo": orderInfo,
                    "redirectUrl": redirectUrl,
                    "ipnUrl": ipnUrl,
                    "lang": "vi",
                    "extraData": extraData,
                    "requestType": requestType,
                    "signature": signature
                };
                mc.setPayloadJSON(momoPayload);
